{
  "vulnerable_symbols": [
    "urlize",
    "Template.render",
    "Environment.from_string"
  ],
  "trigger": "当 Jinja2 模板对攻击者可控字符串应用 urlize filter，且输入为特制长字符串时，正则回溯导致拒绝服务。",
  "preconditions": [
    "模板渲染路径中使用了 urlize filter 处理外部可控变量",
    "外部输入包含可触发正则回溯的长字符串（如大量 [a-zA-Z0-9._-] 与标点组合）"
  ],
  "exploit_evidence": [
    {
      "src": 1,
      "kind": "poc",
      "quote": "11 CVE-2020-28493 jinja2 Yes 09/25/2020 Yeting Li"
    },
    {
      "src": 7,
      "kind": "poc",
      "quote": "Snyk has a proof-of-concept or detailed explanation of how to exploit this vulnerability."
    }
  ],
  "fixed_version": "2.11.3",
  "summary_zh": "Jinja2 2.10 的 urlize 过滤器存在 ReDoS，外部长字符串可致 DoS，请升级 2.11.3。"
}
